declare module '*.css' {
  const text: string;
  export default text;
}

/** Inlined by the build as a data URL. */
declare module '*.svg' {
  const url: string;
  export default url;
}

/** Inlined by the build as a data URL. */
declare module '*.woff2' {
  const url: string;
  export default url;
}
